import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
// Structural rewrite: cooperative CTA-tiled convolution with shared-memory
// staging of reusable input tiles and per-CTA weight staging.
// Each CTA computes a 16x16 output spatial tile for 2 output channels.
// Per input channel: stage 71x71 input halo tile (zero-padded) into shared
// memory, barrier, then all 256 threads accumulate from shared memory.
// Each thread produces 2 outputs (2 accumulators) for oc_base and oc_base+1.
.visible .entry conv2d_3x96_k11_s4_p2(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elems
)
{
    .reg .pred %p, %q;
    .reg .u32 %r_tid, %r_cta, %r_tw, %r_th, %r_ocp, %r_n;
    .reg .u32 %r_tmp, %r_tmp2, %r_idx, %r_row, %r_col, %r_addr;
    .reg .u32 %r_sy, %r_sx, %r_oy, %r_ox, %r_oc0, %r_inb;
    .reg .u32 %r_ic, %r_ky, %r_kx, %r_sin, %r_sw;
    .reg .s32 %s_h0, %s_w0, %s_ih, %s_iw;
    .reg .u64 %rd_in, %rd_wt, %rd_bias, %rd_out, %rd_addr, %rd_off;
    .reg .f32 %f_acc0, %f_acc1, %f_a, %f_b0, %f_b1;
    .shared .align 16 .f32 smem_in[5041];
    .shared .align 16 .f32 smem_w[726];
    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_wt, [wt_ptr];
    ld.param.u64 %rd_bias, [bias_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_cta, %ctaid.x;
    // decompose ctaid.x: tw in [0,4), th in [0,4), ocp in [0,48), n
    rem.u32 %r_tw, %r_cta, 4;
    div.u32 %r_tmp, %r_cta, 4;
    rem.u32 %r_th, %r_tmp, 4;
    div.u32 %r_tmp, %r_tmp, 4;
    rem.u32 %r_ocp, %r_tmp, 48;
    div.u32 %r_n, %r_tmp, 48;
    mov.u32 %r_sin, smem_in;
    mov.u32 %r_sw, smem_w;
    // input halo origin: h0 = th*64 - 2, w0 = tw*64 - 2
    shl.b32 %r_tmp, %r_th, 6;
    cvt.s32.u32 %s_h0, %r_tmp;
    sub.s32 %s_h0, %s_h0, 2;
    shl.b32 %r_tmp, %r_tw, 6;
    cvt.s32.u32 %s_w0, %r_tmp;
    sub.s32 %s_w0, %s_w0, 2;
    // thread spatial coords inside 16x16 tile
    shr.u32 %r_sy, %r_tid, 4;
    and.b32 %r_sx, %r_tid, 15;
    shl.b32 %r_oy, %r_th, 4;
    add.u32 %r_oy, %r_oy, %r_sy;
    shl.b32 %r_ox, %r_tw, 4;
    add.u32 %r_ox, %r_ox, %r_sx;
    // shared input base element index for this thread: sy*284 + sx*4
    mul.lo.u32 %r_inb, %r_sy, 284;
    shl.b32 %r_tmp, %r_sx, 2;
    add.u32 %r_inb, %r_inb, %r_tmp;
    // stage weights for both output channels (contiguous 726 floats)
    mul.lo.u32 %r_tmp, %r_ocp, 726;
    mov.u32 %r_idx, %r_tid;
L_wloop:
    setp.ge.u32 %p, %r_idx, 726;
    @%p bra L_wdone;
    add.u32 %r_tmp2, %r_tmp, %r_idx;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_wt, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
    shl.b32 %r_addr, %r_idx, 2;
    add.u32 %r_addr, %r_addr, %r_sw;
    st.shared.f32 [%r_addr], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_wloop;
L_wdone:
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.u32 %r_ic, 0;
L_ic:
    setp.ge.u32 %p, %r_ic, 3;
    @%p bra L_ic_done;
    // global element offset of channel start: (n*3 + ic)*50176
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 50176;
    // cooperative staging of 71x71 halo tile for this channel (zero pad)
    mov.u32 %r_idx, %r_tid;
L_stage:
    setp.ge.u32 %p, %r_idx, 5041;
    @%p bra L_stage_done;
    div.u32 %r_row, %r_idx, 71;
    rem.u32 %r_col, %r_idx, 71;
    cvt.s32.u32 %s_ih, %r_row;
    add.s32 %s_ih, %s_ih, %s_h0;
    cvt.s32.u32 %s_iw, %r_col;
    add.s32 %s_iw, %s_iw, %s_w0;
    mov.f32 %f_a, 0f00000000;
    setp.lt.s32 %p, %s_ih, 0;
    setp.ge.s32 %q, %s_ih, 224;
    or.pred %p, %p, %q;
    setp.lt.s32 %q, %s_iw, 0;
    or.pred %p, %p, %q;
    setp.ge.s32 %q, %s_iw, 224;
    or.pred %p, %p, %q;
    @%p bra L_stage_store;
    cvt.u32.s32 %r_tmp2, %s_ih;
    mul.lo.u32 %r_tmp2, %r_tmp2, 224;
    add.u32 %r_tmp2, %r_tmp2, %r_tmp;
    cvt.u32.s32 %r_row, %s_iw;
    add.u32 %r_tmp2, %r_tmp2, %r_row;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
L_stage_store:
    shl.b32 %r_addr, %r_idx, 2;
    add.u32 %r_addr, %r_addr, %r_sin;
    st.shared.f32 [%r_addr], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_stage;
L_stage_done:
    bar.sync 0;
    // accumulate 11x11 from shared tile into two output accumulators
    mov.u32 %r_ky, 0;
L_ky:
    setp.ge.u32 %p, %r_ky, 11;
    @%p bra L_ky_done;
    mul.lo.u32 %r_tmp2, %r_ky, 71;
    add.u32 %r_tmp2, %r_tmp2, %r_inb;
    mul.lo.u32 %r_row, %r_ic, 121;
    mul.lo.u32 %r_col, %r_ky, 11;
    add.u32 %r_row, %r_row, %r_col;
    mov.u32 %r_kx, 0;
L_kx:
    setp.ge.u32 %p, %r_kx, 11;
    @%p bra L_kx_done;
    add.u32 %r_idx, %r_tmp2, %r_kx;
    shl.b32 %r_addr, %r_idx, 2;
    add.u32 %r_addr, %r_addr, %r_sin;
    ld.shared.f32 %f_a, [%r_addr];
    add.u32 %r_idx, %r_row, %r_kx;
    shl.b32 %r_addr, %r_idx, 2;
    add.u32 %r_addr, %r_addr, %r_sw;
    ld.shared.f32 %f_b0, [%r_addr];
    add.u32 %r_addr, %r_addr, 1452;
    ld.shared.f32 %f_b1, [%r_addr];
    fma.rn.f32 %f_acc0, %f_a, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a, %f_b1, %f_acc1;
    add.u32 %r_kx, %r_kx, 1;
    bra L_kx;
L_kx_done:
    add.u32 %r_ky, %r_ky, 1;
    bra L_ky;
L_ky_done:
    bar.sync 0;
    add.u32 %r_ic, %r_ic, 1;
    bra L_ic;
L_ic_done:
    // epilogue: add bias and store both output channels
    shl.b32 %r_oc0, %r_ocp, 1;
    cvt.u64.u32 %rd_off, %r_oc0;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_bias, %rd_off;
    ld.global.f32 %f_b0, [%rd_addr];
    ld.global.f32 %f_b1, [%rd_addr + 4];
    add.f32 %f_acc0, %f_acc0, %f_b0;
    add.f32 %f_acc1, %f_acc1, %f_b1;
    setp.ge.u32 %p, %r_oy, 55;
    setp.ge.u32 %q, %r_ox, 55;
    or.pred %p, %p, %q;
    @%p bra L_done;
    mul.lo.u32 %r_tmp, %r_n, 96;
    add.u32 %r_tmp, %r_tmp, %r_oc0;
    mul.lo.u32 %r_tmp, %r_tmp, 55;
    add.u32 %r_tmp, %r_tmp, %r_oy;
    mul.lo.u32 %r_tmp, %r_tmp, 55;
    add.u32 %r_tmp, %r_tmp, %r_ox;
    cvt.u64.u32 %rd_off, %r_tmp;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_out, %rd_off;
    st.global.f32 [%rd_addr], %f_acc0;
    st.global.f32 [%rd_addr + 12100], %f_acc1;
L_done:
    ret;
